CREATE TABLE public.products (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  name text NOT NULL,
  name_en text NULL,
  description text NULL,
  category text NULL,
  selling_price numeric NOT NULL,
  cost_price numeric NULL DEFAULT 0,
  image_url text NULL,
  is_active boolean NULL DEFAULT true,
  created_at timestamptz NULL DEFAULT now(),
  updated_at timestamptz NULL DEFAULT now(),
  current_stock numeric NULL DEFAULT 0,
  min_stock numeric NULL DEFAULT 0,
  is_available_online boolean NULL DEFAULT false,
  online_description text NULL,
  online_sort_order integer NULL DEFAULT 0,
  category_id uuid NULL,
  is_featured boolean NOT NULL DEFAULT false,
  PRIMARY KEY ({, i, d, }),
  CONSTRAINT products_category_id_fkey FOREIGN KEY (category_id) REFERENCES public.product_categories (id) ON UPDATE CASCADE ON DELETE CASCADE
);

CREATE TABLE public.profiles (
  id uuid NOT NULL,
  full_name text NOT NULL,
  role text NOT NULL,
  phone text NULL,
  avatar_url text NULL,
  is_active boolean NULL DEFAULT true,
  created_at timestamptz NULL DEFAULT now(),
  updated_at timestamptz NULL DEFAULT now(),
  PRIMARY KEY ({, i, d, }),
  CONSTRAINT profiles_id_fkey FOREIGN KEY (id) REFERENCES public.auth.users (id) ON UPDATE CASCADE ON DELETE CASCADE
);

CREATE TABLE public.push_subscriptions (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL,
  endpoint text NOT NULL,
  p256dh text NOT NULL,
