CREATE TABLE public.recipe_ingredients (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  recipe_id uuid NULL,
  ingredient_id uuid NULL,
  quantity numeric NOT NULL,
  unit text NOT NULL,
  notes text NULL,
  PRIMARY KEY ({, i, d, }),
  CONSTRAINT recipe_ingredients_recipe_id_fkey FOREIGN KEY (recipe_id) REFERENCES public.recipes (id) ON UPDATE CASCADE ON DELETE CASCADE,
